-- Windows authentication educational model
-- Dialect: PostgreSQL 15+
--
-- Models local accounts, domain principals, logon attempts, NTLM
-- challenge-response concepts, Kerberos ticket lifecycles, service
-- principals, audit events, and resource authorization.
--
-- No real password hashes, NTLM responses, Kerberos keys, or tickets
-- are generated by this schema. Secret material must never be stored
-- in audit tables. Real Windows authentication is performed by Windows
-- security components and domain infrastructure.
--
-- Run in a dedicated learning database. The schema is recreated so
-- that this script can be executed repeatedly.

BEGIN;

DROP SCHEMA IF EXISTS windows_auth_lab CASCADE;
CREATE SCHEMA windows_auth_lab;
SET search_path TO windows_auth_lab, public;

CREATE TYPE account_scope AS ENUM (
    'LOCAL',
    'DOMAIN',
    'SERVICE'
);

CREATE TYPE account_state AS ENUM (
    'ENABLED',
    'DISABLED',
    'LOCKED'
);

CREATE TYPE auth_protocol AS ENUM (
    'LOCAL',
    'NTLM_CONCEPT',
    'KERBEROS_CONCEPT'
);

CREATE TYPE logon_kind AS ENUM (
    'INTERACTIVE',
    'NETWORK',
    'SERVICE',
    'REMOTE_INTERACTIVE'
);

CREATE TYPE auth_outcome AS ENUM (
    'SUCCESS',
    'FAILURE',
    'REJECTED',
    'EXPIRED'
);

CREATE TYPE ticket_kind AS ENUM (
    'TGT',
    'SERVICE'
);

CREATE TYPE ticket_state AS ENUM (
    'ACTIVE',
    'REVOKED',
    'EXPIRED'
);

CREATE TABLE repositories (
    repository_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    repository_name text NOT NULL UNIQUE,
    description text NOT NULL DEFAULT '',
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT repository_name_not_blank
        CHECK (length(trim(repository_name)) > 0)
);

CREATE TABLE accounts (
    account_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    username text NOT NULL,
    scope account_scope NOT NULL,
    domain_name text,
    state account_state NOT NULL DEFAULT 'ENABLED',
    password_verifier bytea,
    created_at timestamptz NOT NULL DEFAULT now(),
    last_successful_logon timestamptz,
    failed_attempts integer NOT NULL DEFAULT 0,
    CONSTRAINT username_not_blank
        CHECK (length(trim(username)) > 0),
    CONSTRAINT failed_attempts_nonnegative
        CHECK (failed_attempts >= 0),
    CONSTRAINT account_scope_domain_consistency
        CHECK (
            (scope = 'LOCAL' AND domain_name IS NULL)
            OR
            (scope = 'DOMAIN' AND domain_name IS NOT NULL
                AND length(trim(domain_name)) > 0)
            OR
            (scope = 'SERVICE' AND domain_name IS NOT NULL
                AND length(trim(domain_name)) > 0)
        ),
    CONSTRAINT account_identity_unique
        UNIQUE (
            username,
            scope,
            domain_name
        )
);

COMMENT ON COLUMN accounts.password_verifier IS
'Optional synthetic verifier for controlled lab exercises only. '
'Never store a plaintext password or a reusable real NTLM response here.';

CREATE TABLE account_groups (
    group_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    group_name text NOT NULL UNIQUE,
    description text NOT NULL DEFAULT '',
    CONSTRAINT group_name_not_blank
        CHECK (length(trim(group_name)) > 0)
);

CREATE TABLE account_group_memberships (
    account_id bigint NOT NULL REFERENCES accounts(account_id)
        ON DELETE CASCADE,
    group_id bigint NOT NULL REFERENCES account_groups(group_id)
        ON DELETE CASCADE,
    granted_at timestamptz NOT NULL DEFAULT now(),
    granted_by_account_id bigint REFERENCES accounts(account_id),
    PRIMARY KEY (account_id, group_id)
);

CREATE TABLE service_principals (
    service_principal_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    service_name text NOT NULL,
    host_name text NOT NULL,
    service_account_id bigint NOT NULL UNIQUE
        REFERENCES accounts(account_id),
    enabled boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT service_name_not_blank
        CHECK (length(trim(service_name)) > 0),
    CONSTRAINT service_host_not_blank
        CHECK (length(trim(host_name)) > 0),
    CONSTRAINT service_principal_unique
        UNIQUE (service_name, host_name)
);

CREATE TABLE authentication_attempts (
    attempt_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    account_id bigint REFERENCES accounts(account_id),
    claimed_username text NOT NULL,
    claimed_domain text,
    protocol auth_protocol NOT NULL,
    logon_type logon_kind NOT NULL,
    outcome auth_outcome NOT NULL,
    source_host text NOT NULL,
    occurred_at timestamptz NOT NULL DEFAULT now(),
    reason_code text NOT NULL,
    correlation_id uuid NOT NULL,
    CONSTRAINT claimed_username_not_blank
        CHECK (length(trim(claimed_username)) > 0),
    CONSTRAINT source_host_not_blank
        CHECK (length(trim(source_host)) > 0),
    CONSTRAINT reason_code_not_blank
        CHECK (length(trim(reason_code)) > 0)
);

COMMENT ON TABLE authentication_attempts IS
'Security event history. Store outcome metadata, never passwords, '
'challenge responses, session keys, or ticket encryption keys.';

CREATE TABLE ntlm_challenges (
    challenge_id uuid PRIMARY KEY,
    server_name text NOT NULL,
    issued_at timestamptz NOT NULL DEFAULT now(),
    expires_at timestamptz NOT NULL,
    consumed_at timestamptz,
    claimed_account_id bigint REFERENCES accounts(account_id),
    response_accepted boolean,
    CONSTRAINT challenge_server_not_blank
        CHECK (length(trim(server_name)) > 0),
    CONSTRAINT challenge_expiry_after_issue
        CHECK (expires_at > issued_at),
    CONSTRAINT challenge_consumption_after_issue
        CHECK (consumed_at IS NULL OR consumed_at >= issued_at)
);

CREATE INDEX ntlm_challenges_active_expiry_idx
    ON ntlm_challenges (expires_at)
    WHERE consumed_at IS NULL;

CREATE TABLE kerberos_tickets (
    ticket_id uuid PRIMARY KEY,
    ticket_type ticket_kind NOT NULL,
    account_id bigint NOT NULL REFERENCES accounts(account_id),
    service_principal_id bigint REFERENCES service_principals(
        service_principal_id
    ),
    parent_tgt_id uuid REFERENCES kerberos_tickets(ticket_id),
    issued_at timestamptz NOT NULL DEFAULT now(),
    expires_at timestamptz NOT NULL,
    state ticket_state NOT NULL DEFAULT 'ACTIVE',
    ticket_reference text NOT NULL UNIQUE,
    CONSTRAINT ticket_expiry_after_issue
        CHECK (expires_at > issued_at),
    CONSTRAINT tgt_has_no_service_target
        CHECK (
            ticket_type <> 'TGT'
            OR service_principal_id IS NULL
        ),
    CONSTRAINT service_ticket_has_target
        CHECK (
            ticket_type <> 'SERVICE'
            OR service_principal_id IS NOT NULL
        ),
    CONSTRAINT tgt_has_no_parent
        CHECK (
            ticket_type <> 'TGT'
            OR parent_tgt_id IS NULL
        ),
    CONSTRAINT service_ticket_requires_parent
        CHECK (
            ticket_type <> 'SERVICE'
            OR parent_tgt_id IS NOT NULL
        )
);

CREATE INDEX kerberos_ticket_account_expiry_idx
    ON kerberos_tickets (account_id, expires_at);

CREATE INDEX kerberos_active_tickets_idx
    ON kerberos_tickets (expires_at)
    WHERE state = 'ACTIVE';

CREATE TABLE resources (
    resource_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    resource_name text NOT NULL UNIQUE,
    description text NOT NULL DEFAULT '',
    CONSTRAINT resource_name_not_blank
        CHECK (length(trim(resource_name)) > 0)
);

CREATE TABLE group_resource_permissions (
    group_id bigint NOT NULL REFERENCES account_groups(group_id)
        ON DELETE CASCADE,
    resource_id bigint NOT NULL REFERENCES resources(resource_id)
        ON DELETE CASCADE,
    can_read boolean NOT NULL DEFAULT false,
    can_write boolean NOT NULL DEFAULT false,
    can_administer boolean NOT NULL DEFAULT false,
    PRIMARY KEY (group_id, resource_id),
    CONSTRAINT permission_requires_capability
        CHECK (can_read OR can_write OR can_administer)
);

CREATE TABLE authenticated_sessions (
    session_id uuid PRIMARY KEY,
    account_id bigint NOT NULL REFERENCES accounts(account_id),
    protocol auth_protocol NOT NULL,
    logon_type logon_kind NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    expires_at timestamptz NOT NULL,
    revoked_at timestamptz,
    source_host text NOT NULL,
    correlation_id uuid NOT NULL,
    CONSTRAINT session_expiry_after_creation
        CHECK (expires_at > created_at),
    CONSTRAINT session_revocation_after_creation
        CHECK (revoked_at IS NULL OR revoked_at >= created_at)
);

CREATE INDEX authenticated_sessions_account_created_idx
    ON authenticated_sessions (account_id, created_at DESC);

CREATE TABLE resource_access_events (
    access_event_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    session_id uuid REFERENCES authenticated_sessions(session_id),
    account_id bigint NOT NULL REFERENCES accounts(account_id),
    resource_id bigint NOT NULL REFERENCES resources(resource_id),
    requested_at timestamptz NOT NULL DEFAULT now(),
    granted boolean NOT NULL,
    denial_reason text NOT NULL DEFAULT ''
);

CREATE INDEX resource_access_events_recent_idx
    ON resource_access_events (requested_at DESC, granted);

-- Prevent accidental ticket creation with inconsistent ticket relationships.
CREATE FUNCTION validate_ticket_relationship()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    parent_record kerberos_tickets%ROWTYPE;
BEGIN
    IF NEW.ticket_type = 'SERVICE' THEN
        SELECT *
          INTO parent_record
          FROM kerberos_tickets
         WHERE ticket_id = NEW.parent_tgt_id;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Parent TGT does not exist';
        END IF;

        IF parent_record.ticket_type <> 'TGT' THEN
            RAISE EXCEPTION 'A service ticket must reference a TGT';
        END IF;

        IF parent_record.account_id <> NEW.account_id THEN
            RAISE EXCEPTION 'Ticket and TGT accounts must match';
        END IF;

        IF NEW.expires_at > parent_record.expires_at THEN
            RAISE EXCEPTION
                'Service ticket cannot outlive its parent TGT';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;

CREATE TRIGGER kerberos_ticket_relationship_guard
BEFORE INSERT OR UPDATE ON kerberos_tickets
FOR EACH ROW
EXECUTE FUNCTION validate_ticket_relationship();

-- Refuse successful logon records for disabled or locked accounts.
-- This guard protects the audit data from contradictory successful events.
CREATE FUNCTION validate_successful_authentication()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    current_state account_state;
BEGIN
    IF NEW.outcome = 'SUCCESS' AND NEW.account_id IS NOT NULL THEN
        SELECT state
          INTO current_state
          FROM accounts
         WHERE account_id = NEW.account_id;

        IF current_state IS DISTINCT FROM 'ENABLED' THEN
            RAISE EXCEPTION
                'Successful authentication requires an enabled account';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;

CREATE TRIGGER authentication_success_guard
BEFORE INSERT OR UPDATE ON authentication_attempts
FOR EACH ROW
EXECUTE FUNCTION validate_successful_authentication();

-- Seed synthetic enterprise identities and resource policies.
INSERT INTO accounts (
    username, scope, domain_name, state, failed_attempts
) VALUES
    ('helpdesk', 'LOCAL', NULL, 'ENABLED', 0),
    ('alex', 'DOMAIN', 'CORP.EXAMPLE', 'ENABLED', 0),
    ('morgan', 'DOMAIN', 'CORP.EXAMPLE', 'ENABLED', 0),
    ('disabled.user', 'DOMAIN', 'CORP.EXAMPLE', 'DISABLED', 0),
    ('intranet-service', 'SERVICE', 'CORP.EXAMPLE', 'ENABLED', 0);

INSERT INTO account_groups (group_name, description) VALUES
    ('Users', 'Ordinary local machine users'),
    ('IT Support', 'Authorized workstation support personnel'),
    ('Domain Users', 'Standard corporate domain users'),
    ('Service Accounts', 'Managed application identities');

INSERT INTO account_group_memberships (account_id, group_id)
SELECT a.account_id, g.group_id
FROM accounts AS a
JOIN account_groups AS g
  ON (
       (a.username = 'helpdesk' AND g.group_name IN ('Users', 'IT Support'))
       OR
       (a.username IN ('alex', 'morgan', 'disabled.user')
        AND g.group_name = 'Domain Users')
       OR
       (a.username = 'intranet-service'
        AND g.group_name = 'Service Accounts')
  );

INSERT INTO service_principals (
    service_name, host_name, service_account_id
)
SELECT 'HTTP', 'intranet.corp.example', account_id
FROM accounts
WHERE username = 'intranet-service';

INSERT INTO resources (resource_name, description) VALUES
    ('password-reset', 'Helpdesk credential reset function'),
    ('intranet.read', 'Read corporate intranet content'),
    ('intranet.publish', 'Publish approved intranet content'),
    ('payroll.admin', 'Restricted payroll administration');

INSERT INTO group_resource_permissions (
    group_id, resource_id, can_read, can_write, can_administer
)
SELECT g.group_id, r.resource_id,
       CASE
           WHEN r.resource_name IN ('password-reset', 'intranet.read')
               THEN true
           ELSE false
       END,
       CASE
           WHEN r.resource_name = 'intranet.publish'
               THEN true
           ELSE false
       END,
       CASE
           WHEN r.resource_name = 'password-reset'
               THEN true
           ELSE false
       END
FROM account_groups AS g
JOIN resources AS r
  ON (
       (g.group_name = 'IT Support'
        AND r.resource_name = 'password-reset')
       OR
       (g.group_name = 'Domain Users'
        AND r.resource_name = 'intranet.read')
  );

INSERT INTO group_resource_permissions (
    group_id, resource_id, can_read, can_write, can_administer
)
SELECT g.group_id, r.resource_id, false, true, false
FROM account_groups AS g
JOIN resources AS r
  ON g.group_name = 'IT Support'
 AND r.resource_name = 'intranet.publish';

-- Demonstrate local, NTLM-concept, and Kerberos-concept audit records.
INSERT INTO authentication_attempts (
    account_id, claimed_username, claimed_domain,
    protocol, logon_type, outcome, source_host,
    reason_code, correlation_id
)
SELECT account_id, username, NULL,
       'LOCAL', 'INTERACTIVE', 'SUCCESS', 'WS-104',
       'LOCAL_CREDENTIALS_ACCEPTED',
       '11111111-1111-4111-8111-111111111111'
FROM accounts
WHERE username = 'helpdesk';

INSERT INTO authentication_attempts (
    account_id, claimed_username, claimed_domain,
    protocol, logon_type, outcome, source_host,
    reason_code, correlation_id
)
SELECT account_id, username, domain_name,
       'NTLM_CONCEPT', 'NETWORK', 'SUCCESS', 'FS-01',
       'SYNTHETIC_CHALLENGE_ACCEPTED',
       '22222222-2222-4222-8222-222222222222'
FROM accounts
WHERE username = 'alex';

INSERT INTO authentication_attempts (
    account_id, claimed_username, claimed_domain,
    protocol, logon_type, outcome, source_host,
    reason_code, correlation_id
)
SELECT account_id, username, domain_name,
       'KERBEROS_CONCEPT', 'NETWORK', 'SUCCESS', 'WEB-01',
       'SYNTHETIC_SERVICE_TICKET_ACCEPTED',
       '33333333-3333-4333-8333-333333333333'
FROM accounts
WHERE username = 'alex';

INSERT INTO authentication_attempts (
    account_id, claimed_username, claimed_domain,
    protocol, logon_type, outcome, source_host,
    reason_code, correlation_id
)
SELECT account_id, username, domain_name,
       'KERBEROS_CONCEPT', 'NETWORK', 'REJECTED', 'WEB-01',
       'ACCOUNT_DISABLED',
       '44444444-4444-4444-8444-444444444444'
FROM accounts
WHERE username = 'disabled.user';

INSERT INTO ntlm_challenges (
    challenge_id, server_name, issued_at, expires_at,
    consumed_at, claimed_account_id, response_accepted
) VALUES
    (
        'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',
        'fileserver.corp.example',
        now() - interval '20 seconds',
        now() + interval '40 seconds',
        now() - interval '10 seconds',
        (SELECT account_id FROM accounts WHERE username = 'alex'),
        true
    ),
    (
        'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',
        'legacy-fileserver.corp.example',
        now() - interval '3 minutes',
        now() - interval '2 minutes',
        NULL,
        NULL,
        NULL
    );

INSERT INTO kerberos_tickets (
    ticket_id, ticket_type, account_id, service_principal_id,
    parent_tgt_id, issued_at, expires_at, state, ticket_reference
)
SELECT
    'cccccccc-cccc-4ccc-8ccc-cccccccccccc',
    'TGT',
    a.account_id,
    NULL,
    NULL,
    now() - interval '1 minute',
    now() + interval '4 minutes',
    'ACTIVE',
    'LAB-TGT-ALEX-001'
FROM accounts AS a
WHERE a.username = 'alex';

INSERT INTO kerberos_tickets (
    ticket_id, ticket_type, account_id, service_principal_id,
    parent_tgt_id, issued_at, expires_at, state, ticket_reference
)
SELECT
    'dddddddd-dddd-4ddd-8ddd-dddddddddddd',
    'SERVICE',
    a.account_id,
    sp.service_principal_id,
    'cccccccc-cccc-4ccc-8ccc-cccccccccccc',
    now() - interval '30 seconds',
    now() + interval '3 minutes',
    'ACTIVE',
    'LAB-SERVICE-ALEX-HTTP-001'
FROM accounts AS a
JOIN service_principals AS sp
  ON sp.service_name = 'HTTP'
WHERE a.username = 'alex';

INSERT INTO authenticated_sessions (
    session_id, account_id, protocol, logon_type,
    created_at, expires_at, source_host, correlation_id
)
SELECT
    'eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee',
    account_id,
    'KERBEROS_CONCEPT',
    'NETWORK',
    now() - interval '30 seconds',
    now() + interval '30 minutes',
    'WEB-01',
    '55555555-5555-4555-8555-555555555555'
FROM accounts
WHERE username = 'alex';

INSERT INTO resource_access_events (
    session_id, account_id, resource_id,
    granted, denial_reason
)
SELECT
    'eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee',
    a.account_id,
    r.resource_id,
    true,
    ''
FROM accounts AS a
JOIN resources AS r ON r.resource_name = 'intranet.read'
WHERE a.username = 'alex';

INSERT INTO resource_access_events (
    session_id, account_id, resource_id,
    granted, denial_reason
)
SELECT
    'eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee',
    a.account_id,
    r.resource_id,
    false,
    'GROUP_PERMISSION_MISSING'
FROM accounts AS a
JOIN resources AS r ON r.resource_name = 'payroll.admin'
WHERE a.username = 'alex';

-- Authentication outcomes grouped by protocol.
SELECT protocol, outcome, count(*) AS attempt_count
FROM authentication_attempts
GROUP BY protocol, outcome
ORDER BY protocol, outcome;

-- Distinguish a disabled identity from an invalid password.
SELECT username, scope, domain_name, state, failed_attempts
FROM accounts
ORDER BY scope, domain_name NULLS FIRST, username;

-- Identify unconsumed challenges that have expired.
SELECT challenge_id, server_name, issued_at, expires_at
FROM ntlm_challenges
WHERE consumed_at IS NULL
  AND expires_at <= now();

-- Check service-ticket relationships and expiration status.
SELECT
    t.ticket_reference,
    t.ticket_type,
    a.username,
    sp.service_name,
    sp.host_name,
    t.state,
    t.expires_at,
    CASE
        WHEN t.state = 'REVOKED' THEN 'REVOKED'
        WHEN t.expires_at <= now() THEN 'EXPIRED'
        ELSE 'TIME_VALID'
    END AS temporal_status
FROM kerberos_tickets AS t
JOIN accounts AS a ON a.account_id = t.account_id
LEFT JOIN service_principals AS sp
  ON sp.service_principal_id = t.service_principal_id
ORDER BY t.issued_at;

-- Evaluate read access by combining session identity, group membership,
-- and resource policy. An authenticated session alone does not grant access.
SELECT
    a.username,
    r.resource_name,
    bool_or(COALESCE(p.can_read, false)) AS read_permitted
FROM authenticated_sessions AS s
JOIN accounts AS a ON a.account_id = s.account_id
CROSS JOIN resources AS r
LEFT JOIN account_group_memberships AS m
  ON m.account_id = a.account_id
LEFT JOIN group_resource_permissions AS p
  ON p.group_id = m.group_id
 AND p.resource_id = r.resource_id
WHERE s.revoked_at IS NULL
  AND s.expires_at > now()
  AND a.state = 'ENABLED'
GROUP BY a.username, r.resource_name
ORDER BY a.username, r.resource_name;

-- Show successful and rejected access attempts together.
SELECT
    a.username,
    r.resource_name,
    e.granted,
    e.denial_reason,
    e.requested_at
FROM resource_access_events AS e
JOIN accounts AS a ON a.account_id = e.account_id
JOIN resources AS r ON r.resource_id = e.resource_id
ORDER BY e.requested_at DESC;

-- Demonstrate transactional failure handling. The nested PL/pgSQL block
-- creates a savepoint-like subtransaction, catches the constraint error,
-- and allows the outer transaction to continue.
DO $$
BEGIN
    BEGIN
        INSERT INTO accounts (
            username, scope, domain_name, state
        ) VALUES (
            'invalid.local.domain',
            'LOCAL',
            'CORP.EXAMPLE',
            'ENABLED'
        );
    EXCEPTION WHEN check_violation THEN
        RAISE NOTICE
            'Rejected invalid local/domain account combination.';
    END;
END;
$$;

-- Attempting to create a service ticket without a parent TGT is rejected
-- by the relational CHECK constraint. The exception is caught so the
-- complete demonstration remains executable.
DO $$
BEGIN
    BEGIN
        INSERT INTO kerberos_tickets (
            ticket_id, ticket_type, account_id,
            service_principal_id, parent_tgt_id,
            issued_at, expires_at, ticket_reference
        )
        SELECT
            'ffffffff-ffff-4fff-8fff-ffffffffffff',
            'SERVICE',
            a.account_id,
            sp.service_principal_id,
            NULL,
            now(),
            now() + interval '1 minute',
            'INVALID-SERVICE-TICKET'
        FROM accounts AS a
        CROSS JOIN service_principals AS sp
        WHERE a.username = 'alex'
        LIMIT 1;
    EXCEPTION WHEN check_violation THEN
        RAISE NOTICE
            'Rejected service ticket without a parent TGT.';
    END;
END;
$$;

COMMIT;
